INSERT INTO lessons (id, module_id, title, slug, lesson_type, order_idx, duration_mins, content_markdown, is_free_preview)
VALUES
  ('f0000000-0000-0000-0000-000000000001', 'e0000000-0000-0000-0000-000000000001', '1.1 The Intuition Behind Query, Key and Value Vectors', 'intuition-q-k-v', 'VIDEO', 1, 28, '# Query, Key, Value Projections\n\nIn this lesson, we break down why self-attention operates as a soft dictionary lookup mechanism.\n\n### Mathematical Formulation\n$$\\text{Attention}(Q, K, V) = \\text{softmax}\\left(\\frac{QK^T}{\\sqrt{d_k}}\\right)V$$\n\n### Key Takeaways\n1. Queries match against Keys to compute relevance weights.\n2. Values are weighted and aggregated to produce token representations.\n3. The scaling factor $\\sqrt{d_k}$ prevents gradient saturation in large embedding dimensions.', true),
  ('f0000000-0000-0000-0000-000000000002', 'e0000000-0000-0000-0000-000000000001', '1.2 Implementing Multi-Head Attention in PyTorch from Scratch', 'implementing-mha-pytorch', 'VIDEO', 2, 42, '# PyTorch MHA Implementation\n\nWe will write clean, vectorized tensor code with no loops.\n\n```python\nimport torch\nimport torch.nn as nn\n\nclass MultiHeadAttention(nn.Module):\n    def __init__(self, d_model: int, num_heads: int):\n        super().__init__()\n        self.d_model = d_model\n        self.num_heads = num_heads\n        self.head_dim = d_model // num_heads\n        self.q_proj = nn.Linear(d_model, d_model)\n        self.k_proj = nn.Linear(d_model, d_model)\n        self.v_proj = nn.Linear(d_model, d_model)\n        self.out_proj = nn.Linear(d_model, d_model)\n```', false)
ON CONFLICT (id) DO NOTHING;

